import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.BiXHgXAn.js";const n="/img/config-namespace-change.png",o="/img/config-namespace-diff.png",g=JSON.parse('{"title":"Integrations","description":"Official and community integrations for Task, including VS Code, JSON schemas, and other tools","frontmatter":{"title":"Integrations","description":"Official and community integrations for Task, including VS Code, JSON schemas, and other tools","section":"Getting Started","docType":"guide","outline":"deep"},"headers":[],"relativePath":"docs/integrations.md","filePath":"next/docs/integrations.md"}'),r={name:"docs/integrations.md"};function l(h,e,c,d,p,u){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to &quot;Integrations&quot;">​</a></h1><h2 id="visual-studio-code-extension" tabindex="-1">Visual Studio Code Extension <a class="header-anchor" href="#visual-studio-code-extension" aria-label="Permalink to &quot;Visual Studio Code Extension&quot;">​</a></h2><p>Task has an <a href="https://marketplace.visualstudio.com/items?itemName=task.vscode-task" target="_blank" rel="noreferrer">official extension for Visual Studio Code</a>. The code for this project can be found in <a href="https://github.com/go-task/vscode-task" target="_blank" rel="noreferrer">our GitHub repository</a>. To use this extension, you must have Task v3.45.3+ installed on your system.</p><p>This extension provides the following features (and more):</p><ul><li>View tasks in the sidebar.</li><li>Run tasks from the sidebar and command palette.</li><li>Go to definition from the sidebar and command palette.</li><li>Run last task command.</li><li>Multi-root workspace support.</li><li>Initialize a Taskfile in the current workspace.</li></ul><p>To get autocompletion and validation for your Taskfile, see the <a href="#schema">Schema</a> section below.</p><p><img src="https://github.com/go-task/vscode-task/blob/main/res/preview.png?raw=true" alt="Task for Visual Studio Code"></p><h3 id="configuration-namespace-change" tabindex="-1">Configuration namespace change <a class="header-anchor" href="#configuration-namespace-change" aria-label="Permalink to &quot;Configuration namespace change&quot;">​</a></h3><p>In v1.0.0 of the extension, the configuration namespace was changed from <code>task</code> to <code>taskfile</code> in order to fix <a href="https://github.com/go-task/vscode-task/issues/56" target="_blank" rel="noreferrer">an issue</a>.</p><p><img src="'+n+'" alt="Configuration namespace change warning"></p><p>If you receive a warning like the one above, you will need to update your settings to use the new <code>taskfile</code> namespace instead:</p><p><img src="'+o+`" alt="Configuration namespace diff"></p><h2 id="schema" tabindex="-1">Schema <a class="header-anchor" href="#schema" aria-label="Permalink to &quot;Schema&quot;">​</a></h2><p>This was initially created by <a href="https://github.com/KROSF" target="_blank" class="github-user-mention">@KROSF</a> in <a href="https://gist.github.com/KROSF/c5435acf590acd632f71bb720f685895" target="_blank" rel="noreferrer">this Gist</a> and is now officially maintained in <a href="https://github.com/go-task/task/blob/main/website/src/public/schema.json" target="_blank" rel="noreferrer">this file</a> and made available at <a href="https://taskfile.dev/schema.json" target="_blank" rel="noreferrer">https://taskfile.dev/schema.json</a>. This schema can be used to validate Taskfiles and provide autocompletion in many code editors:</p><h3 id="visual-studio-code" tabindex="-1">Visual Studio Code <a class="header-anchor" href="#visual-studio-code" aria-label="Permalink to &quot;Visual Studio Code&quot;">​</a></h3><p>To integrate the schema into VS Code, you need to install the <a href="https://marketplace.visualstudio.com/items?itemName=redhat.vscode-yaml" target="_blank" rel="noreferrer">YAML extension</a> by Red Hat. Any <code>Taskfile.yml</code> in your project should automatically be detected and validation/autocompletion should work. If this doesn&#39;t work or you want to manually configure it for files with a different name, you can add the following to your <code>settings.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// settings.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;yaml.schemas&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;https://taskfile.dev/schema.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;**/Taskfile.yml&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;./path/to/any/other/taskfile.yml&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>You can also configure the schema directly inside of a Taskfile by adding the following comment to the top of the file:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># yaml-language-server: $schema=https://taskfile.dev/schema.json</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span></code></pre></div><p>You can find more information on this in the <a href="https://github.com/redhat-developer/yaml-language-server" target="_blank" rel="noreferrer">YAML language server project</a>.</p><h2 id="ai-llm-assistants" tabindex="-1">AI/LLM Assistants <a class="header-anchor" href="#ai-llm-assistants" aria-label="Permalink to &quot;AI/LLM Assistants&quot;">​</a></h2><p>Task documentation is optimized for AI assistants like Claude Code, Cursor, and other LLM-powered development tools through the <a href="https://github.com/okineadev/vitepress-plugin-llms" target="_blank" rel="noreferrer">VitePress LLMs plugin</a>.</p><p>This integration provides:</p><ul><li>Structured documentation in LLM-friendly formats</li><li>Context-optimized content for AI assistants</li><li>Automatic generation of <code>llms.txt</code> and <code>llms-full.txt</code> files</li><li>Enhanced discoverability of Task features for AI tools</li></ul><p>AI assistants can access Task documentation through:</p><ul><li><strong><a href="https://taskfile.dev/llms.txt" target="_blank" rel="noreferrer">llms.txt</a></strong>: Lightweight overview of Task documentation</li><li><strong><a href="https://taskfile.dev/llms-full.txt" target="_blank" rel="noreferrer">llms-full.txt</a></strong>: Complete documentation with all content</li></ul><p>These files are automatically generated and kept in sync with the documentation, ensuring AI assistants always have access to the latest Task features and usage patterns.</p><h2 id="community-integrations" tabindex="-1">Community Integrations <a class="header-anchor" href="#community-integrations" aria-label="Permalink to &quot;Community Integrations&quot;">​</a></h2><p>In addition to our official integrations, there is an amazing community of developers who have created their own integrations for Task:</p><ul><li><a href="https://packagecontrol.io/packages/Taskfile" target="_blank" rel="noreferrer">Sublime Text Plugin</a> [<a href="https://github.com/biozz/sublime-taskfile" target="_blank" rel="noreferrer">source</a>] by <a href="https://github.com/biozz" target="_blank" class="github-user-mention">@biozz</a></li><li><a href="https://plugins.jetbrains.com/plugin/17058-taskfile" target="_blank" rel="noreferrer">IntelliJ Plugin</a> [<a href="https://github.com/lechuckroh/task-intellij-plugin" target="_blank" rel="noreferrer">source</a>] by <a href="https://github.com/lechuckroh" target="_blank" class="github-user-mention">@lechuckroh</a></li><li><a href="https://zed.dev/extensions/taskfile" target="_blank" rel="noreferrer">Zed Extension</a> [<a href="https://github.com/nickalie/zed-taskfile" target="_blank" rel="noreferrer">source</a>] by <a href="https://github.com/nickalie" target="_blank" class="github-user-mention">@nickalie</a></li><li><a href="https://github.com/pycontribs/mk" target="_blank" rel="noreferrer">mk</a> command line tool recognizes Taskfiles natively.</li><li><a href="https://github.com/kyu08/fzf-make" target="_blank" rel="noreferrer">fzf-make</a> fuzzy finder with preview window for make, pnpm, yarn, just &amp; task.</li></ul><p>If you have made something that integrates with Task, please feel free to open a PR to add it to this list.</p>`,31)])])}const f=a(r,[["render",l]]);export{g as __pageData,f as default};
